@startuml

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + firstName : string
  + lastName : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + material : string
  + weight : float
}

class Product {
  + id : string
  + name : string
}

class Client {
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : string
  + dateMade : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
  + quantity : int
}

Machine "*" -- "*" Worker
Machine "1" -- "*" ProductType
ProductType "1" -- "*" Product
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "*" OrderLine
OrderLine "*" -- "1" Product

@enduml

